1142: fn dispatch(
1143:     node: &mut Node,
1144:     request: Request,
1145:     progress: &mut dyn FnMut(u64) -> Result<()>,
1146: ) -> Result<Value> {
1147:     progress(0)?;
1148:     match request {
1149:         Request::Head => node.stats(),
1150:         Request::Submit { .. } => Err("SUBMIT_REQUIRES_WORK_CHECK".into()),
1151:         Request::History { tip, after } => {
1152:             let packets =
1153:                 node.history_with_progress(digest(&tip)?, digest(&after)?, 16, progress)?;
1154:             let next = packets
1155:                 .last()
1156:                 .map(|p| p.id().map(hex::encode))
1157:                 .transpose()?
1158:                 .unwrap_or_else(|| after.clone());
1159:             Ok(serde_json::to_value(Page {
1160:                 schema: if node.settings().is_native_pq_application_v6() {
1161:                     "pon-native-pq-history-v6"
1162:                 } else {
1163:                     "pon-native-history-v1"
1164:                 }
1165:                 .into(),
1166:                 network: hex::encode(node.settings().network()),
1167:                 parameters: hex::encode(node.settings().parameters()),
1168:                 genesis: hex::encode(node.settings().genesis()),
1169:                 complete: next == tip,
1170:                 tip,
1171:                 after,
1172:                 next,
1173:                 packets: packets
1174:                     .iter()
1175:                     .map(|p| p.encode_for_settings(node.settings()).map(hex::encode))
1176:                     .collect::<Result<_>>()?,
1177:             })?)
1178:         }
1179:         Request::Confirm { transaction, block } => {
1180:             let batch = node.confirmations_with_progress(
1181:                 &[(digest(&transaction)?, digest(&block)?)],
1182:                 now()?,
1183:                 progress,
1184:             )?;
1185:             Ok(serde_json::to_value(
1186:                 batch
1187:                     .observations
1188:                     .into_iter()
1189:                     .next()
1190:                     .ok_or("EMPTY_CONFIRMATION")?,
1191:             )?)
1192:         }
1193:         Request::ConfirmMany { queries } => Ok(serde_json::to_value(
1194:             node.confirmations_with_progress(&confirmation_queries(&queries)?, now()?, progress)?,
1195:         )?),
1196:     }
1197: }
1198: fn lock_owner<'a>(
1199:     node: &'a Mutex<Node>,
1200:     progress: &mut dyn FnMut(u64) -> Result<()>,
1201: ) -> Result<MutexGuard<'a, Node>> {
1202:     loop {
1203:         progress(0)?;
1204:         match node.try_lock() {
1205:             Ok(owner) => return Ok(owner),
1206:             Err(TryLockError::Poisoned(_)) => return Err("OWNER_POISONED".into()),
1207:             Err(TryLockError::WouldBlock) => thread::sleep(Duration::from_millis(2)),
1208:         }
1209:     }
1210: }
